import{_ as n,C as o,o as d,c as i,a3 as s,E as a,j as e,a as l}from"./chunks/framework.D6kVjW99.js";const b=JSON.parse('{"title":"تتبّع طلبي للأخذ","description":"افهم صفحة متابعة طلبك: معنى كل حالة، وكيف تدفع عند الكاونتر، وماذا تفعل إن رفض المطعم.","frontmatter":{"title":"تتبّع طلبي للأخذ","description":"افهم صفحة متابعة طلبك: معنى كل حالة، وكيف تدفع عند الكاونتر، وماذا تفعل إن رفض المطعم.","order":95,"role":["TOUS"],"appareil":"WEB","duree":"دقيقتان","objectif":"أن تعرف أين وصل طلبك ومتى تأتي لاستلامه.","routes":["m/suivi/:trackingToken"],"parcours":["H3-11"],"capturesLangue":{},"capturesCouvertes":false},"headers":[],"relativePath":"ar/guide/restaurant/suivre-sa-commande.md","filePath":"ar/guide/restaurant/suivre-sa-commande.md","lastUpdated":1794608916000}'),u={name:"ar/guide/restaurant/suivre-sa-commande.md"};function p(c,t,g,m,_,h){const r=o("Capture");return d(),i("div",null,[t[0]||(t[0]=s('<h1 id="تتبّع-طلبي-للأخذ" tabindex="-1">تتبّع طلبي للأخذ <a class="header-anchor" href="#تتبّع-طلبي-للأخذ" aria-label="Permalink to &quot;تتبّع طلبي للأخذ&quot;">​</a></h1><p>طلبتَ للأخذ من موقع مطعم. بعد الإرسال وصلك <strong>رقم</strong> (مثل <strong>W-017</strong>) وموعد الاستلام ورابط <strong>تتبّع طلبي</strong>. يفتح هذا الرابط صفحة تتحدث وحدها: لا حاجة إلى إعادة تحميلها ولا إلى إنشاء حساب.</p><h2 id="فيمَ-تفيد-هذه-الصفحة" tabindex="-1">فيمَ تفيد هذه الصفحة <a class="header-anchor" href="#فيمَ-تفيد-هذه-الصفحة" aria-label="Permalink to &quot;فيمَ تفيد هذه الصفحة&quot;">​</a></h2><p>تخبرك أين وصل طلبك. هي <strong>ملخص</strong> وليست إيصال بيع ولا فاتورة: الإيصال الحقيقي يُسلَّم إليك عند الكاونتر حين تدفع.</p><p>احتفظ بالرابط لنفسك: هو خاص بطلبك، ومن يملكه يستطيع رؤية الطلب.</p>',5)),a(r,{src:"/captures/restaurant/suivre-sa-commande/40-suivi-fr-a-confirmer.webp",appareil:"telephone",alt:"صفحة المتابعة: «بانتظار التأكيد»",legende:"الحالة قبل قرار المطعم."}),a(r,{src:"/captures/restaurant/suivre-sa-commande/41-suivi-fr-recue-en-file-queued.webp",appareil:"telephone",alt:"صفحة المتابعة: الطلب «تم الاستلام» في الانتظار",legende:"«تم الاستلام» و«سيؤكد المطعم طلبك في أقرب وقت ممكن»."}),t[1]||(t[1]=s('<h2 id="معنى-كل-حالة" tabindex="-1">معنى كل حالة <a class="header-anchor" href="#معنى-كل-حالة" aria-label="Permalink to &quot;معنى كل حالة&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ما تقرؤه</th><th>معناه</th></tr></thead><tbody><tr><td><strong>تم الاستلام</strong></td><td>تعذّر الوصول إلى المطعم في تلك اللحظة. طلبك مسجَّل وسيُؤكَّد في أقرب وقت ممكن.</td></tr><tr><td><strong>بانتظار التأكيد</strong></td><td>ما زال على المطعم أن يوافق. يستغرق ذلك عادة بضع دقائق.</td></tr><tr><td><strong>تم القبول</strong></td><td>وافق المطعم. سيذهب طلبك إلى المطبخ.</td></tr><tr><td><strong>قيد التحضير</strong></td><td>يجري تحضير طلبك.</td></tr><tr><td><strong>جاهز</strong></td><td>الطلب جاهز: تفضّل إلى الكاونتر ومعك رقمك.</td></tr><tr><td><strong>تم تسليمه</strong></td><td>استلمتَ طلبك.</td></tr><tr><td><strong>مرفوض</strong></td><td>لا يستطيع المطعم تحضيره. يظهر السبب.</td></tr><tr><td><strong>ملغى</strong></td><td>لن يتم الطلب، مثلًا لأن المطعم لم يتمكن من تأكيده في الوقت المناسب.</td></tr></tbody></table>',2)),a(r,{src:"/captures/restaurant/suivre-sa-commande/42-suivi-fr-acceptee.webp",appareil:"telephone",alt:"صفحة المتابعة: «تم القبول»",legende:"الحالة بعد القبول في الصندوق."}),t[2]||(t[2]=s('<h2 id="الدفع-عند-الكاونتر" tabindex="-1">الدفع عند الكاونتر <a class="header-anchor" href="#الدفع-عند-الكاونتر" aria-label="Permalink to &quot;الدفع عند الكاونتر&quot;">​</a></h2><p>أنت <strong>لا تدفع شيئًا عبر الإنترنت</strong>. تدفع <strong>عند الكاونتر</strong> عند الاستلام بإعطاء رقمك (مثل W-017). يسلّمك المطعم حينها إيصاله. احرص على الحضور في موعد الاستلام الذي اخترته.</p><h2 id="إن-رفض-المطعم-أو-ألغى" tabindex="-1">إن رفض المطعم أو ألغى <a class="header-anchor" href="#إن-رفض-المطعم-أو-ألغى" aria-label="Permalink to &quot;إن رفض المطعم أو ألغى&quot;">​</a></h2><p>تعرض الصفحة «مرفوض» أو «ملغى» مع السبب إن وُجد (مثل نفاد صنف). لم تدفع شيئًا ولا شيء عليك لإلغائه. يمكنك:</p><ul><li>أن تطلب شيئًا آخر، أو في موعد آخر، من قائمة المطعم؛</li><li>أن تتصل بالمطعم على رقم هاتفه المعروض إن ساورك شك.</li></ul>',5)),a(r,{src:"/captures/restaurant/suivre-sa-commande/43-suivi-fr-refusee.webp",appareil:"telephone",alt:"صفحة المتابعة: «مرفوض»",legende:"«رفض المطعم طلبك» (سبب محدد مسبقًا: نفاد)."}),a(r,{src:"/captures/restaurant/suivre-sa-commande/44-suivi-ar-refusee-avec-motif.webp",appareil:"telephone",alt:"صفحة المتابعة بالعربية: مرفوض بسبب كُتب نصًا",legende:"«مرفوض» والسبب الذي كُتب في الصندوق."}),t[3]||(t[3]=e("h2",{id:"إن-لم-تُفتح-الصفحة",tabindex:"-1"},[l("إن لم تُفتح الصفحة "),e("a",{class:"header-anchor",href:"#إن-لم-تُفتح-الصفحة","aria-label":'Permalink to "إن لم تُفتح الصفحة"'},"​")],-1)),t[4]||(t[4]=e("ul",null,[e("li",null,"«تعذّر العثور على هذا الطلب. تحقق من الرابط الذي وصلك.»: الرابط ناقص أو غير صحيح؛ افتحه من جديد من صفحة التأكيد."),e("li",null,"«تعذّر الاتصال. ستتحدّث الصفحة فور عودة الشبكة.»: انتظر عودة الشبكة وستتحدث الصفحة وحدها.")],-1)),t[5]||(t[5]=e("p",null,"لا يُستعمل اسمك وهاتفك إلا لتسليمك طلبك: يمحوهما المطعم بعد بضعة أسابيع.",-1))])}const T=n(u,[["render",p]]);export{b as __pageData,T as default};
